const llmItems = $input.all();
const originalAds = $("Scrape Facebook Ads").all();

const ads = llmItems.map((item, index) => {
  const ad = item.json.output;
  const original = originalAds[index].json;

  return {
    adNumber: index + 1,
    hook: ad.hook,
    body: ad.body,
    cta: ad.cta,
    adLibraryUrl: original.adLibraryUrl
  };
});

return [
  {
    json: {
      adsForComparison: ads
    }
  }
];
